const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const alle = $input.all();
if (alle.length !== 1) {
  throw new Error("tool_invoke_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten " + alle.length);
}
const e = alle[0].json;
if (KONTEXTE.indexOf(e.context_id) === -1) {
  throw new Error("tool_invoke_invalid_input: context_id nicht im Register");
}
if (!/^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$/.test(String(e.tool_id || ""))) {
  throw new Error("tool_invoke_invalid_input: tool_id fehlt oder ist ungueltig");
}
if (!/^[0-9]+\.[0-9]+\.[0-9]+$/.test(String(e.tool_version || ""))) {
  throw new Error("tool_invoke_invalid_input: tool_version fehlt oder ist ungueltig");
}
return [{ json: {
  context_id: e.context_id,
  tool_id: e.tool_id,
  tool_version: e.tool_version,
  risk_class: e.risk_class || "",
  approval_id: e.approval_id || null,
  approval_status: e.approval_status || null,
  payload: e.payload || {},
  trace_id: e.trace_id || null
} }];

// Vertragstor vor jedem Werkzeugaufruf. Einzige Quelle: jarvis_ops.tool_registry.
const RANG = { A: 1, B: 2, C: 3 };
const e = $('Eingabe pruefen').first().json;
const r = $input.first().json;
let code = "allowed";
let grund = "";
if (r.found !== true && Number(r.versions_known) === 0) {
  code = "tool_not_registered"; grund = "Werkzeug nicht im Register: " + e.tool_id;
} else if (r.found !== true) {
  code = "tool_version_mismatch"; grund = "Version " + e.tool_version + " von " + e.tool_id + " ist nicht registriert";
} else if (r.tool_status === "deprecated") {
  code = "tool_deprecated"; grund = "Werkzeugversion ist ausser Betrieb";
} else if (r.context_allowed !== true) {
  code = "context_not_allowed"; grund = "Werkzeug ist fuer Kontext " + e.context_id + " nicht zugelassen";
} else if (!RANG[e.risk_class]) {
  code = "risk_class_missing"; grund = "risk_class fehlt oder ist unzulaessig";
} else if (RANG[e.risk_class] < RANG[r.registry_class]) {
  code = "risk_class_downgrade"; grund = "Aktion traegt Klasse " + e.risk_class + ", Register verlangt mindestens " + r.registry_class;
} else if (e.risk_class === "C" && (!e.approval_id || e.approval_status !== "approved")) {
  code = "approval_missing"; grund = "Klasse C ohne gueltige Freigabe";
} else if (r.tool_status !== "approved") {
  code = "tool_not_released"; grund = "Werkzeug steht auf " + r.tool_status + ". Freigabe erst nach praktischem Nachweis.";
}
const ok = code === "allowed";
return [{ json: {
  invocation_allowed: ok,
  gate_code: code,
  reason: grund,
  tool_id: e.tool_id,
  tool_version: e.tool_version,
  tool_status: r.tool_status || null,
  registry_class: r.registry_class || null,
  readback_supported: r.found === true ? r.readback_supported : null,
  accepted_methods: r.found === true ? r.accepted_methods : null,
  evidence_limitation: r.found === true ? r.evidence_limitation : null,
  risk_class: e.risk_class || null,
  context_id: e.context_id,
  trace_id: e.trace_id
} }];
